+        const bx = cx + pointer.x * s * .018;
+        const by = cy + pointer.y * s * .008;
+        const rimY = by;
+        const rx = s * .47;
+        const ry = s * .205;
+
+        // Soft cast shadow and reflected firelight.
+        ctx.save();
+        ctx.filter = `blur(${s * .055}px)`;
+        oval(bx, rimY + s * .45, s * .51, s * .10, 'rgba(0,0,0,.86)');
+        oval(bx, rimY + s * .37, s * .34, s * .055, 'rgba(197,71,20,.16)');
