+          ctx.moveTo(-s * .073, 0);
+          ctx.quadraticCurveTo(-s * .055, -s * .084, 0, -s * .092);
+          ctx.quadraticCurveTo(s * .058, -s * .081, s * .077, 0);
+          ctx.quadraticCurveTo(0, s * .021, -s * .073, 0);
+          ctx.fillStyle = cap; ctx.fill();
+          ctx.strokeStyle = 'rgba(244,195,136,.25)'; ctx.lineWidth = s * .003; ctx.stroke();
+          ctx.restore();
+        }
+      }
+
+      function drawGreens(x, y, s) {
+        const leaves = [[-.25, -.10, -.7], [-.18, -.14, -.2], [.26, -.02, .25], [.18, -.015, .72]];
+        for (const [ox, oy, rot] of leaves) {
+          ctx.save();
+          ctx.translate(x + ox * s, y + oy * s);
+          ctx.rotate(rot);
+          ctx.beginPath();
+          ctx.moveTo(0, s * .07);
+          ctx.bezierCurveTo(-s * .07, s * .025, -s * .075, -s * .045, 0, -s * .085);
+          ctx.bezierCurveTo(s * .079, -s * .045, s * .071, s * .025, 0, s * .07);
+          const green = ctx.createLinearGradient(-s * .06, 0, s * .06, 0);
+          green.addColorStop(0, '#17351e'); green.addColorStop(.48, '#5b7e32'); green.addColorStop(1, '#1c4523');
