+          ctx.strokeStyle = 'rgba(187,211,90,.45)'; ctx.lineWidth = s * .002;
+          ctx.beginPath(); ctx.moveTo(0, s * .057); ctx.lineTo(0, -s * .067); ctx.stroke();
+          ctx.restore();
+        }
+      }
+
+      function drawScallions(x, y, s) {
+        const positions = [[-.05,-.17],[.08,-.07],[.14,-.15],[-.17,-.04],[.01,-.02],[.26,-.03],[-.28,-.02]];
+        for (let i = 0; i < positions.length; i++) {
+          const [ox, oy] = positions[i];
+          ctx.save();
+          ctx.translate(x + ox * s, y + oy * s);
+          ctx.rotate(i * 1.7);
+          oval(0, 0, s * .025, s * .010, '#83a945', '#b9d36a', s * .003);
+          oval(0, 0, s * .012, s * .0045, '#254823');
+          ctx.restore();
+        }
+
+        // Chili threads add a small, living accent.
+        for (let i = 0; i < 5; i++) {
+          const ox = (i - 2) * s * .024;
+          path([
+            [x + ox, y - s * .12],
+            [x + ox - s * .055, y - s * (.18 + i * .005)],
+            [x + ox + s * .04, y - s * .20],
+            [x + ox + s * .02, y - s * .25]
+          ], '#b93b20', s * .004, .9);
+        }
+
+        // Sesame seeds.
+        for (const p of seeds.slice(28)) {
+          const angle = p.x * Math.PI * 2;
+          const radius = Math.sqrt(p.y) * s * .31;
+          const sx = x + Math.cos(angle) * radius;
+          const sy = y - s * .01 + Math.sin(angle) * radius * .39;
+          ctx.save(); ctx.translate(sx, sy); ctx.rotate(angle);
+          oval(0, 0, s * .008, s * .0028, p.x > .28 ? '#e7d39d' : '#4b2b18');
+          ctx.restore();
+        }
+      }
+
+      function draw(t) {
+        const portrait = height > width * 1.08;
+        const s = Math.min(width * (portrait ? .93 : .72), height * (portrait ? .60 : .70), 680);
+        const cx = width / 2;
+        const cy = portrait ? height * .61 : height * .59;
+
+        pointer.x = lerp(pointer.x, pointer.tx, reduceMotion.matches ? 1 : .045);
+        pointer.y = lerp(pointer.y, pointer.ty, reduceMotion.matches ? 1 : .045);
+
+        drawBackground(cx, cy, s, t);
+        drawSteam(cx + pointer.x * s * .008, cy, s, t);
+        drawBowl(cx, cy, s, t);
+
+        if (!reduceMotion.matches) raf = requestAnimationFrame(now => draw((now - start) / 1000));
+      }
+
+      function begin() {
+        cancelAnimationFrame(raf);
+        start = performance.now();
+        draw(0);
+      }
+
+      addEventListener('resize', resize, { passive: true });
+      addEventListener('pointermove', e => {
+        pointer.tx = ((e.clientX / width) - .5) * 2;
+        pointer.ty = ((e.clientY / height) - .5) * 2;
+        pointer.active = true;
+        if (reduceMotion.matches) draw(0);
+      }, { passive: true });
+      addEventListener('pointerleave', () => { pointer.tx = 0; pointer.ty = 0; pointer.active = false; });
+      reduceMotion.addEventListener('change', begin);
+
+      resize();
+    })();
+  </script>
+</body>
+</html>

